def find_frames_final(grid):
    """Find all rectangular frames in grid"""
    h, w = len(grid), len(grid[0])
    bg = 3
    found = []

    for r_start in range(h):
        for c_start in range(w):
            if r_start >= h-2 or c_start >= w-2 or grid[r_start][c_start] == bg:
                continue

            color = grid[r_start][c_start]

            for r_end in range(r_start+2, h):
                for c_end in range(c_start+2, w):
                    top_ok = all(grid[r_start][c] == color for c in range(c_start, c_end+1))
                    bottom_ok = all(grid[r_end][c] == color for c in range(c_start, c_end+1))
                    left_ok = all(grid[r][c_start] == color for r in range(r_start, r_end+1))
                    right_ok = all(grid[r][c_end] == color for r in range(r_start, r_end+1))

                    if not (top_ok and bottom_ok and left_ok and right_ok):
                        continue

                    interior = set()
                    for r in range(r_start+1, r_end):
                        for c in range(c_start+1, c_end):
                            interior.add((r, c))

                    if any(grid[r][c] == color for r, c in interior):
                        continue

                    width = c_end - c_start + 1
                    height = r_end - r_start + 1
                    fill = 7 if width % 2 == 1 else 2

                    found.append({
                        'r': r_start, 'c': c_start, 'r_end': r_end, 'c_end': c_end,
                        'color': color, 
                        'width': width, 
                        'height': height,
                        'interior': interior, 
                        'fill': fill
                    })

    return found

