# Create corrected grid
def create_corrected_grid(grid, frames):
    result = [row[:] for row in grid]
    for frame in frames:
        for r, c in frame['interior']:
            result[r][c] = frame['fill']
    return result

frames = sorted(find_frames_final(test_input), key=lambda x: (x['r'], x['c']))
corrected = create_corrected_grid(test_input, frames)

